1	/****************************************************************************
2	 * NuttX linker script for RV1126B EVB (RISC-V RV32IMC)
3	 *
4	 * Memory map:
5	 *   RAM: 0x48c02000, 232KB (0x3a000)
6	 *
7	 * Adapted from the RV1126B SDK reference linker script.
8	 ****************************************************************************/
9	
10	OUTPUT_ARCH("riscv")
11	ENTRY(__start)
12	
13	MEMORY
14	{
15	    /* RV1126B MCU SRAM: 0x48c02000, 232KB */
16	    ram (rwx) : ORIGIN = 0x48c02000, LENGTH = 0x3a000
17	}
18	
19	SECTIONS
20	{
21	    /* Code and read-only data */
22	
23	    .text : {
24	        _stext = .;
25	        KEEP(*(.text.start .text.start.*))  /* Entry point must be first */
26	        *(.text .text.*)
27	        *(.gnu.linkonce.t.*)
28	        *(.rodata .rodata.*)
29	        *(.gnu.linkonce.r.*)
30	
31	        /* Constructors / destructors */
32	
33	        . = ALIGN(4);
34	        KEEP(*(.init))
35	        KEEP(*(.fini))
36	
37	        . = ALIGN(4);
38	        _etext = .;
39	    } > ram
40	
41	    /* Thread-local storage */
42	
43	    .tdata : {
44	        _tls_data = .;
45	        *(.tdata .tdata.*)
46	        _tdata_end = .;
47	    } > ram
48	
49	    .tbss : {
50	        *(.tbss .tbss.*)
51	        _tbss_end = .;
52	    } > ram
53	
54	    /* Initialized data */
55	
56	    _eronly = LOADADDR(.data);
57	
58	    .data : {
59	        _sdata = .;
60	        *(.data .data.*)
61	        *(.gnu.linkonce.d.*)
62	        . = ALIGN(4);
63	        _edata = .;
64	    } > ram AT > ram
65	
66	    /* Small data */
67	
68	    .sdata : {
69	        _gp = . + 0x800;
70	        *(.srodata.cst16) *(.srodata.cst8) *(.srodata.cst4) *(.srodata.cst2)
71	        *(.srodata .srodata.*)
72	        *(.sdata .sdata.* .gnu.linkonce.s.*)
73	        . = ALIGN(4);
74	    } > ram
75	
76	    .sbss : {
77	        *(.sbss .sbss.* .gnu.linkonce.sb.*)
78	        *(.scommon)
79	    } > ram
80	
81	    /* Uninitialized data (BSS) */
82	
83	    .bss : {
84	        _sbss = .;
85	        *(.bss .bss.*)
86	        *(.gnu.linkonce.b.*)
87	        *(COMMON)
88	        . = ALIGN(16);
89	        _ebss = .;
90	    } > ram
91	
92	    /* Heap starts after BSS */
93	
94	    . = ALIGN(16);
95	    _sheap = .;
96	    _eheap = ORIGIN(ram) + LENGTH(ram);
97	}
