171	  return priv->peername;
172	}
173	
174	static struct resource_table *rp_get_resource(struct rptun_dev_s *dev)
175	{
176	  struct k230_rptun_dev_s *priv = as_k230_rptun_dev(dev);
177	  struct rptun_rsc_s *rsc;
178	
179	  if (priv->shmem != NULL)
180	    {
181	      return &priv->shmem->rsc.rsc_tbl_hdr;
182	    }
183	
184	  priv->shmem = SHMEM;
185	
186	  if (priv->master)
187	    {
188	      /* Perform initial setup */
189	
190	      rsc = &priv->shmem->rsc;
191	
192	      rsc->rsc_tbl_hdr.ver          = 1;
193	      rsc->rsc_tbl_hdr.num          = 2;
194	      rsc->rsc_tbl_hdr.reserved[0]  = 0;
195	      rsc->rsc_tbl_hdr.reserved[1]  = 0;
196	      rsc->offset[0]                = offsetof(struct rptun_rsc_s,
197	                                               rpmsg_vdev);
198	
199	      rsc->rpmsg_vdev.type          = RSC_VDEV;
200	      rsc->rpmsg_vdev.id            = VIRTIO_ID_RPMSG;
201	      rsc->rpmsg_vdev.dfeatures     = 1 << VIRTIO_RPMSG_F_NS
202	                                    | 1 << VIRTIO_RPMSG_F_ACK
203	                                    | 1 << VIRTIO_RPMSG_F_BUFSZ;
204	      rsc->rpmsg_vdev.config_len    = sizeof(struct fw_rsc_config);
205	      rsc->rpmsg_vdev.num_of_vrings = VRINGS;
206	
207	      rsc->rpmsg_vring0.align       = VRING_ALIGN;
208	      rsc->rpmsg_vring0.num         = VRING_NR;
209	      rsc->rpmsg_vring0.notifyid    = VRING0_NOTIFYID;
210	      rsc->rpmsg_vring1.align       = VRING_ALIGN;
211	      rsc->rpmsg_vring1.num         = VRING_NR;
212	      rsc->rpmsg_vring1.notifyid    = VRING1_NOTIFYID;
213	      rsc->config.r2h_buf_size      = VRING_SIZE;
214	      rsc->config.h2r_buf_size      = VRING_SIZE;
215	
216	      /* Carveout, reserved 0x1000 for vrings and memory management header */
217	
218	      rsc->offset[1]                = offsetof(struct rptun_rsc_s,
219	                                               carveout);
220	      rsc->carveout.type            = RSC_CARVEOUT;
221	      rsc->carveout.da              = (uintptr_t)rsc + ALIGN_UP(sizeof
222	                                      (struct rptun_rsc_s), VRING_ALIGN);
223	      rsc->carveout.pa              = FW_RSC_U32_ADDR_ANY;
224	      rsc->carveout.len             = VRING_SIZE * VRING_NR * VRINGS +
225	                                      0x1000;
226	      memcpy(rsc->carveout.name, "rpmsg_shm", 10);
227	
228	      priv->shmem->base             = (uintptr_t)priv->shmem;
229	
230	      rpinfo("shmem:%lx, dev:%p\n", priv->shmem->base, dev);
231	    }
232	  else
233	    {
234	      /* TODO: use IPI later, polling now. */
235	
236	      rpinfo("wait for shmem %p...\n", priv->shmem);
237	      while (priv->shmem->base == 0)
238	        {
239	          nxsig_usleep(100);
240	        }
241	
242	      rpinfo("shmem:%lx, dev:%p\n", priv->shmem->base, dev);
243	    }
244	
245	  return &priv->shmem->rsc.rsc_tbl_hdr;
246	}
