302	/****************************************************************************
303	 * Public Functions
304	 ****************************************************************************/
305	
306	int k230_rptun_init(const char *peername)
307	{
308	  struct k230_rptun_dev_s  *dev = &g_rptun_dev;
309	  int                       ret = OK;
310	
311	  memset(dev, 0, sizeof(*dev));
312	
313	#ifdef CONFIG_K230_RPTUN_MASTER
314	  /* master is responsible for initializing shmem */
315	
316	  memset((void *)SHMEM, 0, SHMEM_SIZE);
317	  rpinfo("cleared %ld @ %p\n", SHMEM_SIZE, SHMEM);
318	  dev->master = true;
319	#else
320	  dev->master = false;
321	#endif
322	
323	  ret = k230_ipi_init(RPTUN_IPI_DEVN, RPTUN_IPI_LINE_MASK, RPTUN_IPI_ROLE,
324	                      k230_rptun_callback, dev);
325	  if (ret < 0)
326	    {
327	      rperr("k230_ipi_init failed %d\n", ret);
328	      goto ipierr;
329	    }
330	
331	  /* Configure device */
332	
333	  dev->rptun.ops = &g_k230_rptun_ops;
334	  strncpy(dev->peername, peername, RPMSG_NAME_SIZE);
335	
336	  ret = rptun_initialize(&dev->rptun);
337	  if (ret < 0)
338	    {
339	      rperr("rptun_initialize failed %d!\n", ret);
340	      goto errout;
341	    }
342	
343	  return 0;
344	
345	errout:
346	  k230_ipi_finish(RPTUN_IPI_DEVN, RPTUN_IPI_LINE_MASK);
347	
348	ipierr:
349	  return ret;
350	}
