73	/****************************************************************************
74	 * Private Functions
75	 ****************************************************************************/
76	
77	static int k230_ipi_isr(int irq, void *context, void *args)
78	{
79	  uint32_t  devn = (uintptr_t)args;
80	  bool remote = (g_ipi_confs[devn].role == IPI_ROLE_REMOTE);
81	  uintptr_t regc = remote ? K230_IPI_M2R_INTCLR(devn):
82	                            K230_IPI_R2M_INTCLR(devn);
83	  uintptr_t regs = remote ? K230_IPI_M2R_INTSTS(devn):
84	                            K230_IPI_R2M_INTSTS(devn);
85	  uint32_t  stat = getreg32(regs);
86	  for (uint32_t i = 0; i <= K230_IPI_LINE_MAX; i++)
87	    {
88	      if (stat & (3 << (i << 1)))
89	        {
90	          g_ipi_confs[devn].cbfn(IPI_COMB(devn, i), g_ipi_confs[devn].args);
91	          putreg32(i, regc);
92	        }
93	    }
94	
95	  return 0;
96	}
