98	/****************************************************************************
99	 * Public Functions
100	 ****************************************************************************/
101	
102	int k230_ipi_init(uintptr_t devn, uint16_t mask, uint16_t role,
103	                  ipi_callback_t ipcb, void *args)
104	{
105	  int ret = -EBUSY;
106	  bool master = (role == IPI_ROLE_MASTER);
107	#ifdef CONFIG_K230_IPI_RESET_ON_INIT
108	  static bool mbox_reset = false;
109	#endif
110	
111	  DEBUGASSERT(devn <= K230_IPI_DEVN_MAX);
112	  DEBUGASSERT(mask);
113	  DEBUGASSERT(ipcb);
114	  DEBUGASSERT(role == IPI_ROLE_MASTER || role == IPI_ROLE_REMOTE);
115	
116	  nxmutex_lock(&g_ipi_lock);
117	  if (0 == g_ipi_confs[devn].role)
118	    {
119	      g_ipi_confs[devn].mask = mask;
120	      g_ipi_confs[devn].cbfn = ipcb;
121	      g_ipi_confs[devn].args = args;
122	      g_ipi_confs[devn].role = role;
123	      ret = 0;
124	    }
125	
126	  nxmutex_unlock(&g_ipi_lock);
127	
128	  if (0 == ret)
129	    {
130	#ifdef CONFIG_K230_IPI_RESET_UPON_INIT
131	      /* Reset whole mailbox device */
132	
133	      if (master && !mbox_reset)
134	        {
135	          uint32_t val = getreg32(K230_SOC_RESET_ADDR);
136	          val &= ~(1 << K230_MBOX_RESET_BIT);
137	          putreg32(val, K230_SOC_RESET_ADDR);
138	          up_udelay(K230_RESET_DELAY_US);
139	          val |= (1 << K230_MBOX_RESET_BIT);
140	          putreg32(val, K230_SOC_RESET_ADDR);
141	          up_udelay(K230_RESET_DELAY_US);
142	          mbox_reset = true;
143	          sinfo("mbox reset @ %lx\n", K230_SOC_RESET_ADDR);
144	        }
145	
146	#endif
147	      /* Attach and enable the IRQ */
148	
149	      ret = irq_attach(K230_IPI_IRQ(devn), k230_ipi_isr, (void *)devn);
150	      up_enable_irq(K230_IPI_IRQ(devn));
151	
152	      /* enable IPI device like RTT/Linux does */
153	
154	      uint32_t v = (master ? 3u : 1u) | (mask << 16);
155	      putreg32(v, K230_IPI_R2M_INTEN(devn));
156	      putreg32(v, K230_IPI_M2R_INTEN(devn));
157	    }
158	
159	  sinfo("devn=%ld,lmsk=%x,role=%c,r2me=%x,m2re=%x,ret=%d\n",
160	        devn, mask, master ? 'M' : 'R',
161	        getreg32(K230_IPI_R2M_INTEN(devn)),
162	        getreg32(K230_IPI_M2R_INTEN(devn)), ret);
163	
164	  return ret;
165	}
166	
167	void k230_ipi_notify(uint8_t devn, uint8_t line)
168	{
169	  DEBUGASSERT(devn <= K230_IPI_DEVN_MAX);
170	  DEBUGASSERT(line <= K230_IPI_LINE_MAX);
171	
172	  nxmutex_lock(&g_ipi_lock);
173	  uint16_t role = g_ipi_confs[devn].role;
174	  uint16_t mask = g_ipi_confs[devn].mask;
175	  nxmutex_unlock(&g_ipi_lock);
176	
177	  if ((1 << line) & mask)
178	    {
179	      bool master = (role == IPI_ROLE_MASTER);
180	      uintptr_t regs = master ? K230_IPI_M2R_INTSET(devn):
181	                                K230_IPI_R2M_INTSET(devn);
182	      putreg32(line, regs);
183	    }
184	}
185	
186	void k230_ipi_finish(uint8_t devn, uint16_t mask)
187	{
188	  DEBUGASSERT(devn <= K230_IPI_DEVN_MAX);
189	  DEBUGASSERT(g_ipi_confs[devn].mask == mask);
190	  uint16_t role = g_ipi_confs[devn].role;
191	  DEBUGASSERT(role == IPI_ROLE_MASTER || role == IPI_ROLE_MASTER);
192	
193	  /* reset device and disable interrupts */
194	
195	  bool remote = (role == IPI_ROLE_REMOTE);
196	  putreg32(2u | mask << 16, remote ? K230_IPI_M2R_INTEN(devn):
197	                                     K230_IPI_R2M_INTEN(devn));
198	  up_disable_irq(K230_IPI_IRQ(devn));
199	  irq_detach(K230_IPI_IRQ(devn));
200	
201	  nxmutex_lock(&g_ipi_lock);
202	  memset(g_ipi_confs + devn, 0, sizeof(g_ipi_confs[0]));
203	  nxmutex_unlock(&g_ipi_lock);
204	  sinfo("devn=%d,mask=%x\n", devn, mask);
205	}
206	
207	#endif /* !defined(CONFIG_BUILD_KERNEL) || defined(CONFIG_NUTTSBI) */
208

