 * distributed under the License is distributed on an "AS IS" BASIS,
 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
 * See the License for the specific language governing permissions and
 * limitations under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * RV1126B Mailbox driver for AMP notification (HPMCU ↔ Linux A-core)
 *
 * The RV1126B has 8 mailbox instances (MBOX0-MBOX7).  Each instance has
 * 4 channels and two data directions:
 *
 *   A2B: A-core writes, HPMCU reads   (Linux → HPMCU)
 *   B2A: HPMCU writes, A-core reads   (HPMCU → Linux)
 *
 * For the RPTun/rpmsg link we use:
 *   TX path (HPMCU → Linux): write to MBOX3 A2B FIFO ch0, triggers
 *                             interrupt on Linux side.
 *   RX path (Linux → HPMCU): MBOX0 B2A FIFO ch0 triggers INTMUX
 *                             interrupt on HPMCU side.
 *
 * Register layout (per Rockchip mailbox IP, same for all instances):
 *
 *   0x0000  VER        Version (RO)
 *   0x0004  CON        Control (FIFO clear bits)
 *   0x0008  STATUS     Status (RO, FIFO full/empty flags)
 *   0x000C  A2B_INTEN  A2B interrupt enable
 *   0x0010  A2B_INTST  A2B interrupt status (W1C)
 *   0x0014  B2A_INTEN  B2A interrupt enable
 *   0x0018  B2A_INTST  B2A interrupt status (W1C)
 *   0x0100  FIFO(ch0)  Channel 0 data register (A2B 0x0100, B2A 0x0108)
 *   0x0110  FIFO(ch1)  Channel 1 data register
 *   ...
 *
 * INTEN/INTST bit encoding (per channel, 4 bits each):
 *   bit 0: RX not empty
 *   bit 1: TX empty
 *   bit 2: RX overflow
 *   bit 3: TX overflow
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <assert.h>
#include <debug.h>
#include <errno.h>
#include <stdint.h>

#include <nuttx/arch.h>
#include <nuttx/irq.h>

#include "hardware/rv1126b_memorymap.h"
#include "rv1126b_mailbox.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Register offsets */

#define MBOX_VER_OFFSET       0x0000
#define MBOX_CON_OFFSET       0x0004
#define MBOX_STATUS_OFFSET    0x0008
#define MBOX_A2B_INTEN_OFFSET 0x000c
#define MBOX_A2B_INTST_OFFSET 0x0010
#define MBOX_B2A_INTEN_OFFSET 0x0014
#define MBOX_B2A_INTST_OFFSET 0x0018

/* FIFO base: A2B at 0x100, B2A at 0x108, stride 0x10 per channel */

#define MBOX_A2B_FIFO(ch)     (0x0100 + (ch) * 0x10)
#define MBOX_B2A_FIFO(ch)     (0x0100 + (ch) * 0x10 + 0x08)

/* INTEN/INTST bits: 4 bits per channel */

#define MBOX_INT_RXNE(ch)     (1u << ((ch) * 4 + 0))  /* RX not empty */
#define MBOX_INT_TXE(ch)      (1u << ((ch) * 4 + 1))  /* TX empty */
#define MBOX_INT_RXOVF(ch)    (1u << ((ch) * 4 + 2))  /* RX overflow */
#define MBOX_INT_TXOVF(ch)    (1u << ((ch) * 4 + 3))  /* TX overflow */

/* CON register bits: FIFO clear */

#define MBOX_CON_A2B_CLR(ch)  (1u << (ch))            /* Clear A2B FIFO ch */
#define MBOX_CON_B2A_CLR(ch)  (1u << ((ch) + 4))      /* Clear B2A FIFO ch */

/* Instance base address */

#define MBOX_BASE(n)          (RV1126B_MBOX0_BASE + (n) * 0x10000)

/* INTMUX source for MBOX0 B2A interrupt.
 * TODO: verify against RV1126B TRM.  Common Rockchip values for HPMCU
 * mailbox are INTMUX source 32 or 64 range.  Using a Kconfig override
 * until confirmed.
 */

#define MBOX0_INTMUX_SOURCE   CONFIG_RV1126B_MBOX_INTMUX_SOURCE
#define MBOX0_IRQ             RV1126B_INTMUX_SOURCE_TO_IRQ(MBOX0_INTMUX_SOURCE)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static rv1126b_mbox_callback_t g_mbox_callback;
static void                   *g_mbox_arg;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rv1126b_mbox_isr
 *
 * Description:
 *   ISR for MBOX0 B2A interrupt.  Called when Linux A-core writes to
 *   MBOX0 B2A FIFO (doorbell notification).
 *
 ****************************************************************************/

static int rv1126b_mbox_isr(int irq, void *context, void *arg)
{
  uintptr_t base = MBOX_BASE(RV1126B_MBOX_RX_INST);
  uint32_t  intst;

  /* Read and clear B2A interrupt status for our channel */

  intst = getreg32(base + MBOX_B2A_INTST_OFFSET);
  putreg32(intst, base + MBOX_B2A_INTST_OFFSET);

  /* Invoke the registered callback */

  if (g_mbox_callback != NULL)
    {
      g_mbox_callback(g_mbox_arg);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rv1126b_mailbox_init
 ****************************************************************************/

int rv1126b_mailbox_init(rv1126b_mbox_callback_t callback, void *arg)
{
  uintptr_t rx_base = MBOX_BASE(RV1126B_MBOX_RX_INST);
  uintptr_t tx_base = MBOX_BASE(RV1126B_MBOX_TX_INST);
  int       ret;

  DEBUGASSERT(callback != NULL);

  g_mbox_callback = callback;
  g_mbox_arg      = arg;

  /* Clear RX FIFO to start clean */

  putreg32(MBOX_CON_B2A_CLR(RV1126B_MBOX_RX_CHAN),
           rx_base + MBOX_CON_OFFSET);

  /* Clear any pending B2A interrupt on RX instance */

  putreg32(MBOX_INT_RXNE(RV1126B_MBOX_RX_CHAN) |
           MBOX_INT_RXOVF(RV1126B_MBOX_RX_CHAN),
           rx_base + MBOX_B2A_INTST_OFFSET);

  /* Enable B2A RX-not-empty interrupt on RX instance */

  putreg32(MBOX_INT_RXNE(RV1126B_MBOX_RX_CHAN),
           rx_base + MBOX_B2A_INTEN_OFFSET);

  /* Clear any pending A2B interrupt on TX instance */

  putreg32(MBOX_INT_TXE(RV1126B_MBOX_TX_CHAN),
           tx_base + MBOX_A2B_INTST_OFFSET);

  /* Attach and enable the INTMUX IRQ */

  ret = irq_attach(MBOX0_IRQ, rv1126b_mbox_isr, NULL);
  if (ret < 0)
    {
      rpmsgerr("irq_attach failed: %d\n", ret);
      return ret;
    }

  up_enable_irq(MBOX0_IRQ);

  rpmsginfo("mailbox init: RX MBOX%d ch%d IRQ=%d, TX MBOX%d ch%d\n",
            RV1126B_MBOX_RX_INST, RV1126B_MBOX_RX_CHAN, MBOX0_IRQ,
            RV1126B_MBOX_TX_INST, RV1126B_MBOX_TX_CHAN);

  return OK;
}

/****************************************************************************
 * Name: rv1126b_mailbox_notify
 ****************************************************************************/

void rv1126b_mailbox_notify(void)
{
  uintptr_t tx_base = MBOX_BASE(RV1126B_MBOX_TX_INST);

  /* Write a magic value to the A2B FIFO to trigger Linux-side interrupt.
   * The value itself is not interpreted; it serves as a doorbell.
   */

  putreg32(0x524d5347, /* "RMSG" */
           tx_base + MBOX_A2B_FIFO(RV1126B_MBOX_TX_CHAN));
}

