 * See the License for the specific language governing permissions and
 * limitations under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * RV1126B Mailbox V2 driver for AMP notification (HPMCU ↔ Linux A-core)
 *
 * The RV1126B mailbox uses the V2 single-channel register layout.
 * Each instance has one A2B (host→remote) and one B2A (remote→host)
 * channel with CMD + DATA register pairs.
 *
 * Register layout per instance (from SDK rv1126b.h MBOX_REG):
 *
 *   0x00  A2B_INTEN   bit0=TX_DONE, bit1=RX_DONE, bit8=TRIG_MODE
 *   0x04  A2B_STATUS  bit0=TX_DONE_INT, bit1=RX_DONE_INT (W1C)
 *   0x08  A2B_CMD     32-bit command
 *   0x0C  A2B_DATA    32-bit data
 *   0x10  B2A_INTEN   (same layout as A2B)
 *   0x14  B2A_STATUS  (same layout as A2B, W1C)
 *   0x18  B2A_CMD
 *   0x1C  B2A_DATA
 *
 * AMP mapping (from SDK CMSIS soc.h):
 *
 *   HPMCU_MBOX0 = MBOX4 (base 0x20D00000) — RX from Linux
 *   HPMCU_MBOX3 = MBOX7 (base 0x20D30000) — TX to Linux
 *
 *   Linux writes B2A_CMD on MBOX4 → HPMCU INTMUX IRQ 113
 *   HPMCU writes A2B_CMD on MBOX7 → Linux mailbox IRQ
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <assert.h>
#include <debug.h>
#include <errno.h>
#include <stdint.h>

#include <syslog.h>

#include <nuttx/arch.h>
#include <nuttx/irq.h>

#include "hardware/rv1126b_memorymap.h"
#include "hardware/rv1126b_mailbox.h"
#include "rv1126b_mailbox.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* INTMUX source and IRQ for HPMCU_MBOX0 BB interrupt */

#define MBOX0_INTMUX_SOURCE   RV1126B_MBOX0_BB_INTMUX_SOURCE  /* 113 */
#define MBOX0_IRQ             RV1126B_INTMUX_SOURCE_TO_IRQ(MBOX0_INTMUX_SOURCE)

/* Instance base addresses */

#define MBOX_RX_BASE          RV1126B_MBOX_BASE(RV1126B_MBOX_RX_INST)  /* MBOX4 */
#define MBOX_TX_BASE          RV1126B_MBOX_BASE(RV1126B_MBOX_TX_INST)  /* MBOX7 */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static rv1126b_mbox_callback_t g_mbox_callback;
static void                   *g_mbox_arg;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rv1126b_mbox_isr
 *
 * Description:
 *   ISR for HPMCU_MBOX0 B2A interrupt (INTMUX source 113).
 *   Fires when Linux A-core writes to MBOX4 B2A_CMD.
 *
 ****************************************************************************/

static int rv1126b_mbox_isr(int irq, void *context, void *arg)
{
  uint32_t status;

  /* Read B2A status from RX instance (MBOX4) */

  status = getreg32(MBOX_RX_BASE + RV1126B_MBOX_B2A_STATUS_OFFSET);

  /* Clear pending status (W1C) */

  putreg32(status, MBOX_RX_BASE + RV1126B_MBOX_B2A_STATUS_OFFSET);

  /* Invoke the registered callback */

  if (g_mbox_callback != NULL)
    {
      g_mbox_callback(g_mbox_arg);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rv1126b_mailbox_init
 ****************************************************************************/

int rv1126b_mailbox_init(rv1126b_mbox_callback_t callback, void *arg)
{
  int ret;

  DEBUGASSERT(callback != NULL);

  g_mbox_callback = callback;
  g_mbox_arg      = arg;

  /* Clear any pending B2A status on RX instance (MBOX4) */

  putreg32(RV1126B_MBOX_INT_TX_DONE | RV1126B_MBOX_INT_RX_DONE,
           MBOX_RX_BASE + RV1126B_MBOX_B2A_STATUS_OFFSET);

  /* Enable B2A RX_DONE interrupt on RX instance.
   * Set TRIG_MODE so both CMD and DATA trigger the interrupt.
   */

  putreg32(RV1126B_MBOX_INT_RX_DONE | RV1126B_MBOX_INT_TRIG_MODE,
           MBOX_RX_BASE + RV1126B_MBOX_B2A_INTEN_OFFSET);

  /* Clear any pending A2B status on TX instance (MBOX7) */

  putreg32(RV1126B_MBOX_INT_TX_DONE | RV1126B_MBOX_INT_RX_DONE,
           MBOX_TX_BASE + RV1126B_MBOX_A2B_STATUS_OFFSET);

  /* Attach and enable the INTMUX IRQ for MBOX0 BB */

  ret = irq_attach(MBOX0_IRQ, rv1126b_mbox_isr, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "rv1126b_mailbox: irq_attach failed: %d\n", ret);
      return ret;
    }

  up_enable_irq(MBOX0_IRQ);

  syslog(LOG_INFO,
         "rv1126b_mailbox: RX MBOX%d (B2A) IRQ=%d, TX MBOX%d (A2B)\n",
         RV1126B_MBOX_RX_INST, MBOX0_IRQ, RV1126B_MBOX_TX_INST);

  return OK;
}

/****************************************************************************
 * Name: rv1126b_mailbox_notify
 *
 * Description:
 *   Send a doorbell notification to Linux A-core by writing to MBOX7
 *   A2B_CMD.  The Linux rockchip-mailbox V2 driver will receive this
 *   as a mailbox message with cmd + data.
 *
 ****************************************************************************/

void rv1126b_mailbox_notify(void)
{
  /* Write magic CMD + DATA to trigger Linux-side mailbox IRQ.
   * Linux rockchip-mailbox V2 reads B2A_CMD/B2A_DATA on its RX side.
   * The magic value 0x524d5347 ("RMSG") matches SDK convention.
   */

  putreg32(0x524d5347, /* CMD: "RMSG" */
           MBOX_TX_BASE + RV1126B_MBOX_A2B_CMD_OFFSET);
  putreg32(0,          /* DATA: unused for doorbell */
           MBOX_TX_BASE + RV1126B_MBOX_A2B_DATA_OFFSET);
}

/****************************************************************************
 * contest2026_135_yongwangzhiqian/board/contest_board/chip/rv1126b_rptun.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.
 * The ASF licenses this file to you under the Apache License, Version 2.0
 * (the "License"); you may not use this file except in compliance with
 * the License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS,
 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
 * See the License for the specific language governing permissions and
 * limitations under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * RV1126B RPTun glue for AMP (HPMCU NuttX ↔ Linux A-core)
 *
 * This driver implements the NuttX RPTun interface for the RV1126B HPMCU,
 * using the RV1126B mailbox V2 hardware for inter-core notification and
 * a shared memory region for virtio/rpmsg data exchange.
 *
 * Design follows the K230 RPTun reference (k230_rptun.c).
 *
 * Shared memory layout:
 *   Base: CONFIG_RV1126B_RPTUN_SHM_ADDR (default 0x48c3c000)
 *   Size: CONFIG_RV1126B_RPTUN_SHM_SIZE (default 128KB)
 *
 * The master (Linux) initializes the resource table; the remote (HPMCU)
 * waits for the master's handshake before proceeding.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <assert.h>
#include <debug.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <sys/types.h>

#include <nuttx/nuttx.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/rptun/rptun.h>
#include <nuttx/drivers/addrenv.h>
#include <nuttx/list.h>

#include <arch/barriers.h>

#include "rv1126b_mailbox.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define rpinfo rpmsginfo
#define rpwarn rpmsgwarn
#define rperr  rpmsgerr

/* Vring config parameters (matching K230 / nrf53 defaults) */

#define VRINGS                   2           /* Number of vrings        */
#define VRING_ALIGN              8           /* Vring alignment         */
#define VRING_NR                 8           /* Number of descriptors   */
#define VRING_SIZE               512         /* Size of one descriptor  */

#define VRING_SHMEM              CONFIG_RV1126B_RPTUN_SHM_ADDR
#define VRING0_NOTIFYID          (RSC_NOTIFY_ID_ANY)
#define VRING1_NOTIFYID          (RSC_NOTIFY_ID_ANY)

#define VRING_SHMEM_END          (VRING_SHMEM + CONFIG_RV1126B_RPTUN_SHM_SIZE)

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct rv1126b_rptun_shmem_s
{
  volatile uintptr_t         base;    /* Handshake: master writes its addr */
  struct rptun_rsc_s         rsc;     /* Resource table                    */
};

struct rv1126b_rptun_dev_s
{
  struct rptun_dev_s              rptun;
  rptun_callback_t                callback;
  void                           *arg;
  bool                            master;
  struct rv1126b_rptun_shmem_s   *shmem;
  struct simple_addrenv_s         addrenv[VRINGS];
  char                            peername[RPMSG_NAME_SIZE + 1];
};

#define to_rv1126b_rptun(d) \
  container_of(d, struct rv1126b_rptun_dev_s, rptun)

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static const char      *rp_get_cpuname(struct rptun_dev_s *dev);
static struct resource_table *rp_get_resource(struct rptun_dev_s *dev);
static bool             rp_is_autostart(struct rptun_dev_s *dev);
static bool             rp_is_master(struct rptun_dev_s *dev);
static int              rp_start(struct rptun_dev_s *dev);
static int              rp_stop(struct rptun_dev_s *dev);
static int              rp_notify(struct rptun_dev_s *dev, uint32_t vqid);
static int              rp_set_callback(struct rptun_dev_s *dev,
                                        rptun_callback_t cb, void *arg);
static void             rv1126b_rptun_mbox_cb(void *arg);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct rptun_ops_s g_rv1126b_rptun_ops =
{
  .get_cpuname       = rp_get_cpuname,
  .get_resource      = rp_get_resource,
  .is_autostart      = rp_is_autostart,
  .is_master         = rp_is_master,
  .start             = rp_start,
  .stop              = rp_stop,
  .notify            = rp_notify,
  .register_callback = rp_set_callback,
};

#define SHMEM        ((struct rv1126b_rptun_shmem_s *)VRING_SHMEM)
#define SHMEM_SIZE   sizeof(struct rv1126b_rptun_shmem_s)

static struct rv1126b_rptun_dev_s g_rptun_dev;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static const char *rp_get_cpuname(struct rptun_dev_s *dev)
{
  struct rv1126b_rptun_dev_s *priv = to_rv1126b_rptun(dev);
  return priv->peername;
}

static struct resource_table *rp_get_resource(struct rptun_dev_s *dev)
{
  struct rv1126b_rptun_dev_s *priv = to_rv1126b_rptun(dev);
  struct rptun_rsc_s *rsc;

  if (priv->shmem != NULL)
    {
      return &priv->shmem->rsc.rsc_tbl_hdr;
    }

  priv->shmem = SHMEM;

  if (priv->master)
    {
      /* Master (Linux) initializes the resource table.
       * HPMCU is always remote; Linux is master.
       * But if built as master for testing, we init here.
       */

      rsc = &priv->shmem->rsc;

      rsc->rsc_tbl_hdr.ver          = 1;
      rsc->rsc_tbl_hdr.num          = 2;
      rsc->rsc_tbl_hdr.reserved[0]  = 0;
      rsc->rsc_tbl_hdr.reserved[1]  = 0;
      rsc->offset[0]                = offsetof(struct rptun_rsc_s,
                                               rpmsg_vdev);

      rsc->rpmsg_vdev.type          = RSC_VDEV;
      rsc->rpmsg_vdev.id            = VIRTIO_ID_RPMSG;
      rsc->rpmsg_vdev.dfeatures     = 1 << VIRTIO_RPMSG_F_NS
                                    | 1 << VIRTIO_RPMSG_F_ACK
                                    | 1 << VIRTIO_RPMSG_F_BUFSZ;
      rsc->rpmsg_vdev.config_len    = sizeof(struct fw_rsc_config);
      rsc->rpmsg_vdev.num_of_vrings = VRINGS;

      rsc->rpmsg_vring0.align       = VRING_ALIGN;
      rsc->rpmsg_vring0.num         = VRING_NR;
      rsc->rpmsg_vring0.notifyid    = VRING0_NOTIFYID;
      rsc->rpmsg_vring1.align       = VRING_ALIGN;
      rsc->rpmsg_vring1.num         = VRING_NR;
      rsc->rpmsg_vring1.notifyid    = VRING1_NOTIFYID;
      rsc->config.r2h_buf_size      = VRING_SIZE;
      rsc->config.h2r_buf_size      = VRING_SIZE;

      /* Carveout: reserved 0x1000 for vrings and memory management */

      rsc->offset[1]                = offsetof(struct rptun_rsc_s,
                                               carveout);
      rsc->carveout.type            = RSC_CARVEOUT;
      rsc->carveout.da              = (uintptr_t)rsc + ALIGN_UP(sizeof
                                      (struct rptun_rsc_s), VRING_ALIGN);
      rsc->carveout.pa              = FW_RSC_U32_ADDR_ANY;
      rsc->carveout.len             = VRING_SIZE * VRING_NR * VRINGS +
                                      0x1000;
      memcpy(rsc->carveout.name, "rpmsg_shm", 10);

      /* Signal readiness to remote */

      priv->shmem->base             = (uintptr_t)priv->shmem;

      rpinfo("master shmem:%lx\n", priv->shmem->base);
    }
  else
    {
      /* Remote (HPMCU): wait for master to write shmem->base */

      rpinfo("waiting for master shmem at %p...\n", priv->shmem);
      while (priv->shmem->base == 0)
        {
          nxsig_usleep(100);
        }

      rpinfo("master shmem ready: %lx\n", priv->shmem->base);
    }

  return &priv->shmem->rsc.rsc_tbl_hdr;
}

