/****************************************************************************
 * Name: rv1126b_rptun_mbox_cb
 *
 * Description:
 *   Mailbox RX callback — invoked from the MBOX4 B2A ISR when Linux
 *   sends a doorbell notification.
 *
 ****************************************************************************/

static void rv1126b_rptun_mbox_cb(void *arg)
{
  struct rv1126b_rptun_dev_s *dev = arg;
  if (dev->callback)
    {
      dev->callback(dev->arg, RPTUN_NOTIFY_ALL);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rv1126b_rptun_init
 *
 * Description:
 *   Initialize the RV1126B RPTun driver for AMP communication.
 *   Sets up the mailbox notification path and registers with the
 *   RPTun framework.
 *
 * Input Parameters:
 *   peername - Name of the remote CPU (e.g., "ap")
 *
 * Returned Value:
 *   OK on success; negative errno on failure.
 *
 ****************************************************************************/

int rv1126b_rptun_init(const char *peername)
{
  struct rv1126b_rptun_dev_s *dev = &g_rptun_dev;
  int ret;

  memset(dev, 0, sizeof(*dev));

  /* HPMCU is always the remote (Linux is master) */

  dev->master = false;

  /* Initialize mailbox hardware and attach RX callback */

  ret = rv1126b_mailbox_init(rv1126b_rptun_mbox_cb, dev);
  if (ret < 0)
    {
      rperr("mailbox_init failed: %d\n", ret);
      return ret;
    }

  /* Configure RPTun device */

  dev->rptun.ops = &g_rv1126b_rptun_ops;
  strncpy(dev->peername, peername, RPMSG_NAME_SIZE);

  ret = rptun_initialize(&dev->rptun);
  if (ret < 0)
    {
      rperr("rptun_initialize failed: %d\n", ret);
      return ret;
    }

  rpinfo("rptun init: peer=%s shmem=0x%x\n", peername, VRING_SHMEM);
  return OK;
}

