114	int openh264_decoder_enqueue(struct openh264_decoder_s *decoder,
115	                             void *data, int64_t pts, int size)
116	{
117	  DECODING_STATE state;
118	
119	  memset(&decoder->bufinfo, 0, sizeof(SBufferInfo));
120	  memset(decoder->pdst, 0, sizeof(decoder->pdst));
121	
122	  if (decoder->remaining_frames == 0)
123	    {
124	      /* When data is NULL and remaining_frames has
125	       * not been assigned, call DecodeFrame2 to obtain
126	       * the pending buffer.
127	       */
128	
129	      decoder->bufinfo.uiInBsTimeStamp = pts;
130	      state = (*decoder->dec)->DecodeFrame2(decoder->dec,
131	                                            data,
132	                                            size,
133	                                            decoder->pdst,
134	                                            &decoder->bufinfo);
135	      if (state != dsErrorFree)
136	        {
137	          syslog(LOG_ERR, "hostdec - decode failed 0x%04x\n", state);
138	          return -EINVAL;
139	        }
140	
141	      if (data == NULL)
142	        {
143	          (*decoder->dec)->GetOption(decoder->dec,
144	                            DECODER_OPTION_NUM_OF_FRAMES_REMAINING_IN_BUFFER,
145	                            &decoder->remaining_frames);
146	        }
147	    }
148	  else
149	    {
150	      /* When remaining_frames is assigned and greater than
151	       * zero, call FlushFrame to get the last buffers.
152	       */
153	
154	      state = (*decoder->dec)->FlushFrame(decoder->dec,
155	                                          decoder->pdst,
156	                                          &decoder->bufinfo);
157	      if (state != dsErrorFree)
158	        {
159	          syslog(LOG_ERR, "hostdec - flush failed 0x%04x\n", state);
160	          return -EINVAL;
161	        }
162	
163	      decoder->remaining_frames--;
164	    }
165	
166	  return decoder->bufinfo.iBufferStatus;
167	}
