169	int openh264_decoder_dequeue(struct openh264_decoder_s *decoder,
170	                             void *data, int64_t *pts, uint32_t *size)
171	{
172	  uint8_t *dst_addr = data;
173	  int plane;
174	
175	  for (plane = 0; plane < 3; plane++)
176	    {
177	      uint8_t *src_addr = decoder->pdst[plane];
178	      int width  = decoder->bufinfo.UsrData.sSystemBuffer.iWidth;
179	      int height = decoder->bufinfo.UsrData.sSystemBuffer.iHeight;
180	      int stride = decoder->bufinfo.UsrData.sSystemBuffer.iStride[0];
181	      int row;
182	
183	      if (plane > 0)
184	        {
185	          /* UV plane stride is iStride[1] */
186	
187	          width  = width  / 2;
188	          height = height / 2;
189	          stride = decoder->bufinfo.UsrData.sSystemBuffer.iStride[1];
190	        }
191	
192	      for (row = 0; row < height; row++)
193	        {
194	          memcpy(dst_addr, src_addr, width);
195	          src_addr += stride;
196	          dst_addr += width;
197	        }
198	    }
199	
200	  *pts  = decoder->bufinfo.uiOutYuvTimeStamp;
201	  *size = decoder->bufinfo.UsrData.sSystemBuffer.iWidth  *
202	          decoder->bufinfo.UsrData.sSystemBuffer.iHeight * 3 / 2;
203	
204	  return decoder->remaining_frames;
205	}
